const raw = $input.first().json;
const body = raw.body || raw;
const errors = [];
const mode = body.mode;
if (!['magic_link', 'guest'].includes(mode)) errors.push('mode_invalid');
if (!body.client_idempotency_key || !/^[0-9a-f-]{36}$/i.test(body.client_idempotency_key)) errors.push('idempotency_key_invalid');
if (!Array.isArray(body.lines) || body.lines.length === 0) errors.push('lines_empty');
if (!body.requested_delivery_date) errors.push('delivery_date_missing');
if (mode === 'magic_link' && !body.token) errors.push('token_missing');
if (mode === 'guest') {
  if (!body.store_name) errors.push('store_name_missing');
  if (!body.contact_phone) errors.push('phone_missing');
  if (!body.delivery_address) errors.push('address_missing');
}
if (Array.isArray(body.lines)) {
  body.lines.forEach((line, idx) => {
    if (!line.sku) errors.push('lines[' + idx + '].sku_missing');
    if (!Number.isInteger(line.quantity_boxes) || line.quantity_boxes < 1) errors.push('lines[' + idx + '].quantity_invalid');
  });
}

const ok = errors.length === 0;
const skuList = Array.isArray(body.lines) ? body.lines.map(l => l.sku).filter(Boolean) : [];
const esc = (s) => String(s).replace(/"/g, '\\"');
const skuClauses = skuList.map(s => '{SKU}="' + esc(s) + '"');
const skuFilter = skuClauses.length === 0 ? 'FALSE()' : (skuClauses.length === 1 ? skuClauses[0] : 'OR(' + skuClauses.join(',') + ')');
const tokenForLookup = mode === 'magic_link' ? body.token : '__GUEST_NO_TOKEN__';

return [{
  json: {
    ok,
    errors,
    body,
    mode,
    client_idempotency_key: body.client_idempotency_key,
    sku_filter_formula: skuFilter,
    customer_token: tokenForLookup,
    requested_delivery_date: body.requested_delivery_date
  }
}];

const products = ($input.first().json.records || []).map(r => ({ id: r.id, fields: r.fields }));
const v = $('Validate Input').json;
const body = v.body;

const bySku = {};
products.forEach(p => {
  const sku = p.fields['SKU'];
  bySku[sku] = {
    id: p.id,
    sku,
    name: p.fields['품목명'],
    unit_price: p.fields['박스 단가'],
    xero_item_code: p.fields['Xero Item Code']
  };
});

const priced = body.lines.map(l => {
  const m = bySku[l.sku];
  if (!m) return { sku: l.sku, quantity_boxes: l.quantity_boxes, error: 'unknown_sku' };
  return {
    sku: l.sku,
    product_id: m.id,
    name: m.name,
    xero_item_code: m.xero_item_code,
    quantity_boxes: l.quantity_boxes,
    unit_price: m.unit_price,
    line_subtotal: Math.round(m.unit_price * l.quantity_boxes * 100) / 100
  };
});

const unknown = priced.filter(l => l.error);
if (unknown.length > 0) {
  return [{ json: { ok: false, error_code: 'unknown_sku', status_code: 422, unknown_skus: unknown.map(l => l.sku), body, mode: v.mode } }];
}

const subtotal = Math.round(priced.reduce((s, l) => s + l.line_subtotal, 0) * 100) / 100;
const MOQ = 150;
const moqPass = subtotal >= MOQ;

return [{
  json: {
    ok: moqPass,
    error_code: moqPass ? null : 'below_moq',
    status_code: moqPass ? 200 : 422,
    moq_minimum: MOQ,
    subtotal,
    lines: priced,
    body,
    mode: v.mode,
    client_idempotency_key: v.client_idempotency_key,
    customer_token: v.customer_token,
    requested_delivery_date: v.requested_delivery_date
  }
}];

const customerSearch = $input.first().json;
const compute = $('Compute & MOQ').json;
const body = compute.body;
const mode = compute.mode;
const customer = (customerSearch.records || [])[0];

if (mode === 'magic_link' && !customer) {
  return [{ json: { ok: false, error_code: 'token_invalid', status_code: 401, lines: compute.lines, subtotal: compute.subtotal } }];
}

const customerFields = customer ? customer.fields : {};
const customerId = customer ? customer.id : null;

const order_fields = {
  'client_idempotency_key': compute.client_idempotency_key,
  '고객 상태': customerId ? '등록완료' : '미배정',
  '출하 상태': '접수',
  '결제 상태': '미결제',
  'requested_delivery_date': compute.requested_delivery_date,
  '상호': customerId ? (customerFields['상호'] || '') : (body.store_name || ''),
  '연락처': customerId ? (customerFields['연락처'] || '') : (body.contact_phone || ''),
  '기본 배송지': customerId ? (customerFields['기본 배송지'] || '') : (body.delivery_address || ''),
  '이번 주문 배송지': body.delivery_override_address || ''
};

if (customerId) {
  order_fields['고객'] = [customerId];
  const pt = customerFields['Payment term'];
  if (pt) order_fields['Payment term'] = pt;
}

return [{
  json: {
    ok: true,
    order_fields,
    lines: compute.lines,
    subtotal: compute.subtotal,
    customer_id: customerId,
    customer_name: customerFields['상호'] || body.store_name || ''
  }
}];

const created = $input.first().json;
const orderId = created.id;
const orderNo = (created.fields || {})['주문번호'];
const prep = $('Prepare Order').json;
const lines = prep.lines;
const compute = $('Compute & MOQ').json;

const recordsBody = {
  records: lines.map(l => ({
    fields: {
      'label': (orderNo ? ('ORD-' + orderNo) : 'ORD-?') + '-' + (l.xero_item_code || l.sku.slice(0, 3)),
      '오더': [orderId],
      '제품': [l.product_id],
      '수량': l.quantity_boxes,
      '단가': l.unit_price
    }
  })),
  typecast: true
};

return [{
  json: {
    order_id: orderId,
    order_no: orderNo,
    records_body: recordsBody,
    lines,
    subtotal: compute.subtotal,
    requested_delivery_date: compute.requested_delivery_date,
    customer_id: prep.customer_id
  }
}];
